            neighs.append((nr, nc))
    return neighs

def bfs_from(cell_list, target_color, excluded_cells=None):
    """BFS from starting cells through cells of target_color"""
    if excluded_cells is None:
        excluded_cells = set()

    visited = set()
    queue = deque()
    for r, c in cell_list:
        if (r, c) in excluded_cells:
            continue
        if grid[r][c] == target_color:
            visited.add((r, c))
            queue.append((r, c))

    count = 0
    while queue:
        r, c = queue.popleft()
        count += 1
        for nr, nc in get_4_neighbors(grid, r, c):
            if (nr, nc) not in visited and (nr, nc) not in excluded_cells:
                if grid[nr][nc] == target_color:
                    visited.add((nr, nc))
                    queue.append((nr, nc))
    return count

