        nr, nc = r+dr, c+dc
        if 0 <= nr < len(grid) and 0 <= nc < n and grid[nr][nc] == 5:
            diag_neighbors.append((nr, nc))

    return {
        'orthogonal': neighbors,
        'diagonal': diag_neighbors,
        'total_5_neighbors': len(neighbors) + len(diag_neighbors)
    }

