# What if we're looking for rectangles where ONE corner is missing?
def find_incomplete_rectangles(grid):
    """Find axis-aligned rectangles with exactly one corner of opposite color"""
    n = len(grid)
    m = len(grid[0])
    rects = []

    for r1 in range(n):
        for c1 in range(m):
            color1 = grid[r1][c1]
            for r2 in range(r1+1, n):
                for c2 in range(c1+1, m):
                    color2 = grid[r2][c2]
                    if color1 == color2:
                        # Check if other corners match or have opposite color
                        corners_match = [
                            grid[r1][c2] == color1 and grid[r2][c1] == color1,  # both match
                            grid[r1][c2] != color1 and grid[r2][c1] != color1,  # both opposite
                        ]
                        for match in corners_match:
                            rects.append(((r1,c1), (r2,c2), match))
    return rects

